/// <summary>
/// Provides formatted greeting messages.
/// </summary>
public sealed class Greeter
{
    /// <summary>
    /// Returns a greeting for the given user.
    /// </summary>
    /// <param name="name">Target user name.</param>
    /// <returns>Formatted greeting string.</returns>
    public string Hello(string name)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        return $"Hi {name.Trim()}";
    }
}

