/// <summary>
/// Formats normalized tag labels.
/// </summary>
public sealed class TagFormatter
{
    /// <summary>
    /// Builds a uppercase badge label for a valid tag.
    /// </summary>
    /// <param name="tag">Target tag text.</param>
    /// <returns>Formatted badge string.</returns>
    public string FormatBadge(string tag)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(tag);
        return $"[{tag.Trim()}]";
    }
}

